// Live values — the brush settings the canvas reads on every stamp.
const val = (k) => ({ value: nb.get(k), type: typeof nb.get(k) });
return {
  brush_color: val('brush_color'),
  brush_size:  val('brush_size'),   // number
  brush_shape: val('brush_shape'),  // string ('round' | 'square')
  clear_at:    val('clear_at'),     // timestamp; changes on each Clear press
};
